const petals=Array.from({length:12},(_,i)=>`<ellipse cx="140" cy="82" rx="19" ry="51" transform="rotate(${i*30} 140 140)"/>`).join('');
document.querySelector('.flowers').innerHTML=Array.from({length:4},(_,i)=>`<svg class="flower" viewBox="0 0 280 440"><defs>
<linearGradient id="petal-${i}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b6dce4"/><stop offset=".28" stop-color="#f7f0ec"/><stop offset=".52" stop-color="#e3d4ee"/><stop offset=".77" stop-color="#fae3df"/><stop offset="1" stop-color="#ffffe9"/></linearGradient>
<radialGradient id="pollen-${i}" cx=".35" cy=".3" r=".8"><stop stop-color="#fae8a2"/><stop offset=".5" stop-color="#eac775"/><stop offset="1" stop-color="#d19a88"/></radialGradient>
<linearGradient id="leaf-${i}" x2="1" y2="1"><stop stop-color="#c9dfb7"/><stop offset=".5" stop-color="#a6c3ae"/><stop offset="1" stop-color="#8b9d98"/></linearGradient>
<filter id="grain-${i}" x="-5%" y="-5%" width="110%" height="110%" color-interpolation-filters="sRGB"><feTurbulence type="fractalNoise" baseFrequency=".85" numOctaves="3" seed="${i+14}" result="noise"/><feColorMatrix in="noise" type="saturate" values="0"/><feComponentTransfer result="grain"><feFuncR type="linear" slope="1.05" intercept=".32"/><feFuncG type="linear" slope="1.05" intercept=".32"/><feFuncB type="linear" slope="1.05" intercept=".32"/></feComponentTransfer><feBlend in="SourceGraphic" in2="grain" mode="multiply"/><feComposite in2="SourceGraphic" operator="in"/></filter>
</defs><g filter="url(#grain-${i})"><path d="M140 142Q105 280 152 445" fill="none" stroke="#9db39c" stroke-width="4"/><path d="M132 335Q50 331 67 270Q118 276 132 335M133 295Q198 295 207 237Q152 244 133 295" fill="url(#leaf-${i})"/><g fill="url(#petal-${i})" stroke="#ddd9e0" stroke-opacity=".4" stroke-width=".65">${petals}</g><circle cx="140" cy="140" r="29" fill="url(#pollen-${i})"/></g></svg>`).join('');
const dialog=document.querySelector('#brief');document.querySelector('#brief-open').addEventListener('click',()=>dialog.showModal());document.querySelector('#brief-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const values=new FormData(e.target);const content=`ROOTFORCE.DEV — БРИФ\n\nПроект: ${values.get('project')}\n\nИдея:\n${values.get('idea')}\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='rootforce-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);document.querySelector('#brief-status').textContent='Бриф готов. Файл сохранён через загрузки браузера.'});


